import{_ as d,o as r,c as e,a2 as a}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"核心属性","description":"","frontmatter":{},"headers":[],"relativePath":"guide/characters-attributes.md","filePath":"guide/characters-attributes.md","lastUpdated":1786201985000}'),o={name:"guide/characters-attributes.md"};function s(n,t,h,i,c,l){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="核心属性" tabindex="-1">核心属性 <a class="header-anchor" href="#核心属性" aria-label="Permalink to &quot;核心属性&quot;">​</a></h1><p>角色拥有 <strong>力量、敏捷、智力</strong> 三大属性。<strong>核心属性</strong>是角色从这三大属性中，**选择（或被指定）**其中一个成为自己最主要的属性，是角色数值计算中需要参考的重要数值。</p><p>属性由 <strong>基础属性</strong> 和 <strong>额外属性</strong> 相加而成，核心属性也如此：</p><table tabindex="0"><thead><tr><th>属性类型</th><th>来源</th></tr></thead><tbody><tr><td><strong>基础属性</strong></td><td>由初始属性、属性成长、等级等因素计算（<code>STR</code>/<code>AGI</code>/<code>INT</code>）</td></tr><tr><td><strong>额外属性</strong></td><td>通过装备、技能、特效等方式获得的属性加成（<code>ExSTR</code>/<code>ExAGI</code>/<code>ExINT</code>）</td></tr></tbody></table><blockquote><p>核心属性通常是角色自行选择的，但某些机制可以<strong>强制指定</strong>（被指定），例如魔法卡包的同频共振（<code>Resonance</code>）会强制转换角色的核心属性。见 <a href="/guide/prefabricated-entities.html">预制实体 - 魔法卡包</a>。</p></blockquote><hr><h2 id="攻击力提升" tabindex="-1">攻击力提升 <a class="header-anchor" href="#攻击力提升" aria-label="Permalink to &quot;攻击力提升&quot;">​</a></h2><p>核心属性会按 1:1 转换为攻击力：</p><ul><li>每提升 1 点<strong>基础核心属性</strong> → 提升 1 点<strong>基础攻击力</strong></li><li>每提升 1 点<strong>额外核心属性</strong> → 提升 1 点<strong>额外攻击力</strong></li></ul><hr><h2 id="力量" tabindex="-1">力量 <a class="header-anchor" href="#力量" aria-label="Permalink to &quot;力量&quot;">​</a></h2><p>力量是身体控制类属性的来源（如力量豁免），同时提供生存与输出能力：</p><table tabindex="0"><thead><tr><th>每 1 点力量</th><th>加成</th></tr></thead><tbody><tr><td>最大生命值</td><td>+13</td></tr><tr><td>生命回复</td><td>+0.15</td></tr><tr><td>物理护甲</td><td>+0.75</td></tr><tr><td>暴击伤害</td><td>+0.575%</td></tr></tbody></table><h2 id="敏捷" tabindex="-1">敏捷 <a class="header-anchor" href="#敏捷" aria-label="Permalink to &quot;敏捷&quot;">​</a></h2><p>敏捷提供行动速度与闪避、暴击的成长（如敏捷豁免）：</p><table tabindex="0"><thead><tr><th>每 1 点敏捷</th><th>加成</th></tr></thead><tbody><tr><td>行动速度</td><td>+0.65</td></tr><tr><td>闪避率</td><td>+0.175%</td></tr><tr><td>暴击率</td><td>+0.25%</td></tr></tbody></table><h2 id="智力" tabindex="-1">智力 <a class="header-anchor" href="#智力" aria-label="Permalink to &quot;智力&quot;">​</a></h2><p>智力是心智控制类属性的来源（如智力豁免），同时是<strong>魔法瓶颈</strong>的判定基准：</p><table tabindex="0"><thead><tr><th>每 1 点智力</th><th>加成</th></tr></thead><tbody><tr><td>最大魔法值</td><td>+8</td></tr><tr><td>魔法消耗减少</td><td>0.125%</td></tr><tr><td>爆发能量消耗减少</td><td>0.075%</td></tr><tr><td>加速系数</td><td>+0.125%</td></tr><tr><td>冷却缩减</td><td>+0.25%</td></tr><tr><td>魔法回复</td><td>+0.1</td></tr></tbody></table><blockquote><p>三大属性对于提高角色的整体能力值都至关重要。魔法瓶颈与智力的关系见 <a href="/guide/skills-magic.html">魔法 - 魔法瓶颈和魔法效能</a>。</p></blockquote>',20)])])}const u=d(o,[["render",s]]);export{g as __pageData,u as default};
